#include <vector>
#include <deque>

using namespace std;

class Solution {
public:
    int findMaxValueOfEquation(vector<vector<int>>& points, int k) {
        deque<pair<int, int>> dq; // (y - x, x)
        int res = INT_MIN;

        for (auto& p : points) {
            int x = p[0], y = p[1];

            while (!dq.empty() && x - dq.front().second > k)
                dq.pop_front();

            if (!dq.empty())
                res = max(res, dq.front().first + y + x);

            while (!dq.empty() && dq.back().first <= y - x)
                dq.pop_back();

            dq.emplace_back(y - x, x);
        }

        return res;
    }
};
